<template>
  <div class="row" :style="'width: ' + width + '%;'">
    <q-table
      class="text-uppercase sticky-header transparent-header full-width"
      :rows="tableRows"
      :columns="columns as any"
      row-key="id"
      :table-header-style="{ backgroundColor: '#d4d4d4' }"
      :no-data-label="$t('no_data_found')"
    >
      <template v-slot:header="props">
        <q-tr :props="props" class="" :class="''">
          <q-th
            v-for="col in props.cols"
            :key="col.name"
            :props="props"
            :class="''"
          >
            <span :class="''">{{ col.label }}</span>
          </q-th>
        </q-tr>
      </template>

      <template v-slot:body="props">
        <q-tr
          :props="props"
          :id="props.key"
          class="po_iterateable_item compact-table-tr"
          tabindex="0"
          :class="props.rowIndex % 2 == 0 ? '' : 'alternative-row'"
          :data-id="props.key"
        >
          <template v-for="col in props.cols" :key="col.name" :props="props">
            <q-td
              style="width: 50px"
              v-if="col.name === 'action'"
              :data-id="props.key"
              class="actions q-ml-auto"
              :class="''"
            >
              <f-btn
                appearance="tertiary"
                @click="
                  deleteConfirm = true;
                  deleting_row = props.row;
                "
                :icon="'delete'"
                class="q-mr-sm"
              />
            </q-td>

            <q-td v-else :data-id="props.key">
              <span :class="''">
                {{ props.row[col.name] }}
              </span>
            </q-td>
          </template>
        </q-tr>
      </template>
    </q-table>
  </div>

  <q-dialog v-model="deleteConfirm" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('sure') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          data-cy="cancel"
          color="primary"
          v-close-popup
        />
        <q-btn
          flat
          :label="$t('delete')"
          data-cy="delete-popup"
          color="primary"
          v-close-popup
          @click="deleteSupplierItemNumber(deleting_row)"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { documentPOApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { isTopLevelUserAdmin } from 'src/utils/UserDetails';
import { notify } from 'src/components/notifications/notify';
// import  { supplierItemNumberMocked } from 'src/supplier/constant';

export default defineComponent({
  el: '#app',
  props: {
    width: {
      type: Number,
      default: 70,
    },
    supplierId: {
      type: String,
      default: '',
    },
    onSearch: {
      type: String,
    },
  },
  mixins: [helperMixin],
  components: {},
  data() {
    return {
      isAdmin: ref(false),
      searchItem: ref(''),
    };
  },
  mounted: function () {
    this.initView();
  },
  computed: {},
  watch: {
    async onSearch() {
      this.searchItem = this.onSearch?.toLowerCase() || '';
      await this.prepareSupplierItemNumberList();
    },
  },
  methods: {
    initView() {
      this.isAdmin = isTopLevelUserAdmin();
      this.setupSupplierItemNumberList();
    },

    setupSupplierItemNumberList() {
      this.tableRows = [];
      this.prepareColumns();
      this.prepareSupplierItemNumberList();
    },

    prepareColumns() {
      this.columns = [
        {
          name: 'supplier_id',
          label: this.$t('supplier_id'),
          align: 'left',
          field: 'supplier_id',
        },
        {
          name: 'item_number',
          label: this.$t('item_number'),
          align: 'left',
          field: 'item_number',
        },
        {
          name: 'supplier_item_number',
          label: this.$t('supplier_item_number'),
          align: 'left',
          field: 'supplier_item_number',
        },
      ];

      if (this.isAdmin) {
        this.columns.push({
          name: 'action',
          label: this.$t('action'),
          align: 'left',
          field: 'action',
        });
      }
    },

    async prepareSupplierItemNumberList() {
      try {
        let queryParams = {};
        if (this.supplierId) {
          queryParams = { supplier_id: this.supplierId };
        }
        const response =
          await documentPOApiService.getAllSupplierItemNumbers(queryParams);
        if (!response.hasOwnProperty('success') || response.success === false) {
          throw response;
        }

        let data = response.data as dynamicObj;

        // data = supplierItemNumberMocked

        data = data.filter((item: unknown) => {
          const typedItem = item as {
            supplier_id: string;
            item_number: string;
            supplier_item_number: string;
          };
          return (
            typedItem.supplier_id.toLowerCase().includes(this.searchItem) ||
            typedItem.item_number.toLowerCase().includes(this.searchItem) ||
            typedItem.supplier_item_number
              .toLowerCase()
              .includes(this.searchItem)
          );
        });

        const rows = [] as dynamicObj[];
        for (const [index, record] of Object.entries(data)) {
          const newRow = {
            id: record.id,
            supplier_id: record.supplier_id,
            item_number: record.item_number,
            supplier_item_number: record.supplier_item_number,
          } as dynamicObj;
          rows.push(newRow);
        }

        rows.sort((a, b) => {
          return a.supplier_id - b.supplier_id;
        });
        this.tableRows = rows;
        this.$forceUpdate();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async deleteSupplierItemNumber(row: any) {
      try {
        this.showLoading();
        const response = await documentPOApiService.deleteSupplierItemNumber(
          row.id,
        );
        if (
          !response.hasOwnProperty('success') ||
          response.hasOwnProperty('success') === false
        ) {
          throw response;
        }

        this.tableRows = this.tableRows.filter(
          (item: any) => item.id !== row.id,
        );
        notify.success(this.$t('operation_sucessfull'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    return {
      deleteConfirm: ref(false),
      columns: [] as dynamicObj[],
      tableRows: [] as dynamicObj[],
      deleting_row: ref({} as dynamicObj),
    };
  },
});
</script>

<style lang="scss" scoped></style>
